head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jlddst90007";
scwin.kosdaqSeg = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.kosdaqSeg = $c.util.getComponent('kosdaqSeg');
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jlddst90007.onpageload' });
    }
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init = async function () {
    $c.util.getComponent("dma_fnSearchAjaxsubmitReq").set("method", "findStockIsu");
    await scwin.fnSearchInit();
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        $(this).find("input:radio[name=ipt_marketType]").click(function() {
                scwin.fnShowKosdaqSeg($(this));
        });
        await scwin.init();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst90007.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { /* TODO Stage2: [sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0 */ };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name searchForm_onsubmit
 * @description searchForm onsubmit 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.searchForm_onsubmit = function(e){
    try {
        return false;

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst90007.searchForm_onsubmit' }); }
};

/**
 * @method
 * @name rd_marketType2_onclick
 * @description rd_marketType2 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.rd_marketType2_onclick = function(e){
    try {
        clearBtnImage()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst90007.rd_marketType2_onclick' }); }
};

/**
 * @method
 * @name btn_fnSearchInit_onclick
 * @description btn_fnSearchInit 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_fnSearchInit_onclick = async function(e){
    try {
        await scwin.fnSearchInit(); return false;

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst90007.btn_fnSearchInit_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fnSearch_ajaxsubmit
 * @description fn Search ajaxsubmit 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnSearch_ajaxsubmit = async function () {
    const sbmOptions = {
        id: "tx_fnSearch_ajaxsubmit",
        method: "post",
        action: "/common/stockisu.do",
        ref: "dma_fnSearchAjaxsubmitReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name fnSearchInit
 * @description fn Search Init 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearchInit = async function () {
    $c.util.getComponent("dma_fnSearchAjaxsubmitReq").set("pageIndex", "1");
    await scwin.fnSearch();
};

/**
 * @method
 * @name reflectCorpName
 * @description reflect Corp Name 처리
 * @returns {void}
 * @hidden N
 */
scwin.reflectCorpName = function () {
    let nm = $c.util.getComponent('ipt_stockIsuNm').getValue();
    nm = encodeURI(nm);
    $c.util.getComponent('ipt_stockIsuNm').setValue(nm);
};

/**
 * @method
 * @name fnSearch
 * @description fn Search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearch = async function () {
    scwin.setCodeName();
    $c.util.getComponent("dma_fnSearchAjaxsubmitReq").set("marketType", "#marketType");
    $c.util.getComponent("dma_fnSearchAjaxsubmitReq").set("method", "findStockIsu");
    $c.util.getComponent('ipt_beginIndex').setValue("");
    await scwin.tx_fnSearch_ajaxsubmit();
};

/**
 * @method
 * @name fnSearchCallBack
 * @description fn Search Call Back 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.fnSearchCallBack = function (data) {
    (($c.util.getComponent('contents')) && ($c.util.getComponent('contents')).removeAll ? ($c.util.getComponent('contents')).removeAll() : (($c.util.getComponent('contents')) && ($c.util.getComponent('contents')).setValue ? ($c.util.getComponent('contents')).setValue('') : void 0)).append(data);
};

/**
 * @method
 * @name setStockInfo
 * @description set Stock Info 처리
 * @param {*} ipt_marketType ipt_marketType
 * @param {String} isuSrtCd isuSrtCd
 * @param {*} isuEngAbbrv isuEngAbbrv
 * @param {String} isuCd isuCd
 * @param {String} indNm indNm
 * @param {String} listDd listDd
 * @returns {void}
 * @hidden N
 */
scwin.setStockInfo = function (ipt_marketType, isuSrtCd, isuEngAbbrv, isuCd, indNm, listDd) {
    (((((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).scwin || {})) !== scwin && typeof (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).scwin || {})).setStockInfo === 'function' ? (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).scwin || {})).setStockInfo(ipt_marketType, isuSrtCd, isuEngAbbrv, isuCd, indNm, listDd) : void 0), $c.win.closePopup([ipt_marketType, isuSrtCd, isuEngAbbrv, isuCd, indNm, listDd]));
    this.close();
};

/**
 * @method
 * @name setCodeName
 * @description set Code Name 처리
 * @returns {void}
 * @hidden N
 */
scwin.setCodeName = function () {
    $c.util.getComponent('ipt_stockIsuCd').setValue("");
    $c.util.getComponent('ipt_stockIsuNm').setValue("");
    let stockIsu = $c.util.getComponent('ipt_stockIsu').getValue(); if (stockIsu == null) { stockIsu = ''; }
    stockIsu = stockIsu.toUpperCase();
    if (stockIsu == null) {
        return;
    }
    if (stockIsu === "") {
        return;
    }
    if (stockIsu.length === 6) {
        if ($c.num.isNumber($c.util.getComponent('ipt_stockIsu').getValue())) {
            $c.util.getComponent('ipt_stockIsuCd').setValue(stockIsu);
            $c.util.getComponent('ipt_stockIsuNm').setValue("");
            return;
        }
    }
    $c.util.getComponent('ipt_stockIsuCd').setValue("");
    $c.util.getComponent('ipt_stockIsuNm').setValue(stockIsu);
};

/**
 * @method
 * @name fnShowKosdaqSeg
 * @description fn Show Kosdaq Seg 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.fnShowKosdaqSeg = function (obj) {
    if (obj.val() === "2") {
        scwin.kosdaqSeg.setStyle("display", "");
    } else {
        scwin.kosdaqSeg.setStyle("display", "none");
    }
    $("#searchForm").find("input:radio[name=rd_kosdaqSegment]:input#rSeg").prop("checked", true);
};
